#!/usr/bin/env python3
"""Anchored, verified source transform for the favorites-perf fix.
Fails closed if any anchor does not match exactly once."""
import base64, pathlib, sys

def dec(s): return base64.b64decode(s).decode()

OPS = [
    ('replace', 'lib/services/manga/storage/manga_manual_merge_repository.dart', 'ICBib29sIF9oZWFsZWRHZW5yZXMgPSBmYWxzZTsK', ''),
    ('replace', 'lib/services/manga/storage/manga_manual_merge_repository.dart', 'ICAgICAgfSwgY29uZmxpY3RBbGdvcml0aG06IENvbmZsaWN0QWxnb3JpdGhtLnJlcGxhY2UpOwogICAgICByZXR1cm4gaGVhbGVkOwogICAgfSBjYXRjaCAoXykgewogICAgICByZXR1cm4gMDsKICAgIH0KICB9Cg==', 'ICAgICAgfSwgY29uZmxpY3RBbGdvcml0aG06IENvbmZsaWN0QWxnb3JpdGhtLnJlcGxhY2UpOwogICAgICByZXR1cm4gaGVhbGVkOwogICAgfSBjYXRjaCAoZXJyb3IpIHsKICAgICAgX2xhc3RIZWFsRXJyb3IgPSBlcnJvcjsKICAgICAgcmV0dXJuIDA7CiAgICB9CiAgfQo='),
    ('replace', 'lib/services/manga/storage/manga_manual_merge_repository.dart', '', ''),
    ('replace', 'lib/services/manga/storage/manga_manual_merge_repository.dart', '', ''),
    ('replace', 'lib/services/manga/storage/manga_manual_merge_repository.dart', 'ICAgICAgICA6IGNhbmRpZGF0ZXMKICAgICAgICAgICAgICAud2hlcmUoKHJlY29yZCkgPT4gcmVjb3JkLmNvdmVyVXJscy5jb250YWlucyhwcm9wb3NlZENvdmVyKSkKICAgICAgICAgICAgICAuZmlyc3RPck51bGwKICAgICAgICAgICAgICA/LndvcmsKICAgICAgICAgICAgICAud29ya0lkOwogICAgZmluYWwgcmVzdWx0ID0gYXdhaXQgZGIudHJhbnNhY3Rpb24oKHR4KSBhc3luYyB7Cg==', ''),
    ('replace', 'lib/services/manga/storage/manga_manual_merge_repository.dart', '', ''),
    ('replace', 'lib/services/manga/storage/manga_manual_merge_repository.dart', '', ''),
    ('replace', 'lib/services/manga/storage/manga_manual_merge_repository.dart', '', ''),
    ('replace', 'lib/services/manga/manga_browse_local_state_loader.dart', '', ''),
    ('replace', 'test/services/manga/storage/manga_manual_merge_repository_test.dart', 'ICB0ZWFyRG93bigoKSBhc3luYyB7CiAgICBNYW5nYUV4dGVybmFsSWRlbnRpdHlBY2NvdW50U2NvcGUuc2V0QWN0aXZlU3luY0FjY291bnRVaWQobnVsbCk7CiAgICBhd2FpdCBkYXRhYmFzZS5jbG9zZSgpOwogICAgYXdhaXQgdGVtcC5kZWxldGUocmVjdXJzaXZlOiB0cnVlKTsKICB9KTsK', ''),
    ('insert_before_final_brace', 'test/services/manga/storage/manga_manual_merge_repository_test.dart', '', ''),
    ('replace', 'test/services/manga/manga_browse_local_state_loader_test.dart', 'aW1wb3J0ICdwYWNrYWdlOmZsdXR0ZXJfdGVzdC9mbHV0dGVyX3Rlc3QuZGFydCc7', 'aW1wb3J0ICdkYXJ0OmNvbnZlcnQnOwoKaW1wb3J0ICdwYWNrYWdlOmZsdXR0ZXJfdGVzdC9mbHV0dGVyX3Rlc3QuZGFydCc7'),
    ('replace', 'test/services/manga/manga_browse_local_state_loader_test.dart', 'ICB9KTsKfQoKZmluYWwgY2xhc3MgX0hvbWVTdW1tYXJ5RXhlY3V0b3IgaW1wbGVtZW50cyBEYXRhYmFzZUV4ZWN1dG9yIHs=', ''),
    ('append', 'test/services/manga/manga_browse_local_state_loader_test.dart', '', ''),
]

def main():
    root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else ".")
    for kind, rel, old, new in OPS:
        p = root / rel
        text = p.read_text()
        if kind == "replace":
            old, new = dec(old), dec(new)
            n = text.count(old)
            if n != 1:
                raise SystemExit(f"ANCHOR FAIL {rel}: found {n} (need 1)")
            text = text.replace(old, new)
        elif kind == "insert_before_final_brace":
            snippet = dec(old).rstrip("\n")
            idx = text.rfind("\n}")
            if idx < 0:
                raise SystemExit(f"ANCHOR FAIL {rel}: no final brace")
            text = text[:idx] + snippet + text[idx:]
        elif kind == "append":
            snippet = dec(old)
            text = text.rstrip("\n") + "\n" + snippet
        else:
            raise SystemExit(f"unknown op {kind}")
        p.write_text(text)
        print(f"applied {kind}: {rel}")
    print("ALL ANCHORS OK")

if __name__ == "__main__":
    main()
